/**
 * Generates supabase/seed.sql from src/data/menu.ts, so the database prices always match
 * the website's single source of truth. Run after any menu change: npm run db:seed
 */
import { writeFileSync } from 'node:fs';
import { addOns, products } from '../src/data/menu.ts';

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;

const lines: string[] = [
  '-- GENERATED by scripts/generate-menu-seed.ts from src/data/menu.ts. Do not edit by hand.',
  '-- Re-run `npm run db:seed` after changing the menu, then run this file in Supabase.',
  'begin;',
  'delete from public.menu_variants;',
  'delete from public.menu_add_ons;',
  'delete from public.menu_products;',
  '',
];

for (const p of products) {
  const name = p.portion ? `${p.name} (${p.portion})` : p.name;
  lines.push(
    `insert into public.menu_products (id, name, category_id, price) values (${q(p.id)}, ${q(name)}, ${q(p.categoryId)}, ${p.variants ? 'null' : p.price});`,
  );
  for (const v of p.variants ?? []) {
    lines.push(`insert into public.menu_variants (product_id, id, label, price) values (${q(p.id)}, ${q(v.id)}, ${q(v.label)}, ${v.price});`);
  }
}
lines.push('');
for (const a of addOns) {
  lines.push(`insert into public.menu_add_ons (id, name, price, category_id) values (${q(a.id)}, ${q(a.name)}, ${a.price}, ${q(a.categoryId)});`);
}
lines.push('commit;', '');

writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n'));
console.log(`[seed] ${products.length} products, ${addOns.length} add-ons → supabase/seed.sql`);
